TireContactFrame tire_contact_frame(
    const Model& model,
    const State& state,
    const SampleInput& input,
    std::size_t tire_index
) {
    const Tire& t = model.tires[tire_index];
    const int frame_body = tire_frame_body(t);
    const int center_body = tire_center_body(t);
    const Vec3 center_local = tire_center_local(t);
    const Vec3 center = state_point(state, center_body, center_local);
    const Vec3 vc = state_point_velocity(state, center_body, center_local);
    const double road_height =
        (tire_index < input.road_z.size() ? input.road_z[tire_index] : 0.0)
        + road_profile_height(model, state, tire_index);
    const double road_slope = road_profile_slope(model, state, tire_index);
    const double road_v =
        (tire_index < input.road_v.size() ? input.road_v[tire_index] : 0.0)
        + road_slope * vc.x;
    TireContactFrame frame;
    frame.frame_body = frame_body;
    frame.center = center;
    frame.center_velocity = vc;
    frame.road_height = road_height;
    frame.road_velocity = road_v;
    frame.compression = t.radius + road_height - center.z;
    frame.compression_rate = road_v - vc.z;
    frame.longitudinal_slip = tire_index < state.tire_sx.size()
        ? state.tire_sx[tire_index] : 0.0;
    frame.lateral_slip = tire_index < state.tire_sy.size()
        ? state.tire_sy[tire_index] : 0.0;
    frame.loaded_radius = std::max(
        t.radius - std::max(frame.compression, 0.0), 1e-9
    );
    return frame;
}

