// §8-D13: lifted out of `assemble_tire_forces` so the tire force law survives a
// translation-unit boundary.  The former `[&]` lambda captured only read-only
// scalars plus the two `Tire`-derived results `fx`/`fy`/`utilization`; the call
// site therefore reproduces the lambda exactly, and the accumulation order is
// unchanged.

void pac2002_evaluate_forces(
    const Tire& tire,
    double normal_force,
    bool allow_longitudinal,
    bool allow_lateral,
    bool combined_slip,
    double limited_longitudinal_slip,
    double limited_lateral_slip,
    double limited_camber,
    const Pac2002TurnSlip& turn_slip,
    double& fx,
    double& fy,
    double& utilization
) {
    const double limited_load = pac2002_clamp_load(tire, normal_force);
    fx = allow_longitudinal
        ? pac2002_pure_force(
            tire, limited_longitudinal_slip, limited_load, false,
            limited_camber, turn_slip
        )
        : 0.0;
    fy = allow_lateral
        ? pac2002_pure_force(
            tire, limited_lateral_slip, limited_load, true,
            limited_camber, turn_slip
        )
        : 0.0;
    if (combined_slip) {
        fx = pac2002_combined_longitudinal_force(
            tire, limited_longitudinal_slip,
            limited_lateral_slip, limited_load, limited_camber, fx
        );
        fy = pac2002_combined_lateral_force(
            tire, limited_longitudinal_slip,
            limited_lateral_slip, limited_load, limited_camber, fy
        );
    }
    const double limit_x = pac2002_force_limit(
        tire, limited_load, false, limited_camber
    );
    const double limit_y = pac2002_force_limit(
        tire, limited_load, true, limited_camber
    );
    utilization = std::sqrt(
        std::pow(fx/limit_x, 2)+std::pow(fy/limit_y, 2)
    );
    if (!combined_slip && utilization > 1.0) {
        fx /= utilization;
        fy /= utilization;
    }
}

